// Package sqlserver turns SQL Server on for an application generated by
// Clarity: importing it is enough.
//
//	import _ "github.com/petervdpas/Clarity/runtimes/go/sqlserver"
//
// Through go-mssqldb: decimals are DECIMAL, dates DATE and DATETIME2, bools
// BIT. The location is an ADO.NET connection string or a sqlserver:// URL,
// as the driver reads them. A migration step runs in one transaction.
package sqlserver

import (
	"database/sql"
	"errors"

	"github.com/golang-sql/civil"
	mssql "github.com/microsoft/go-mssqldb"
	"github.com/petervdpas/Clarity/runtimes/go/clarity"
)

// foreignKey is the error of a broken reference.
const foreignKey = 547

func init() { clarity.UseServer(clarity.Mssql, open) }

// value is a date or a date and time as the driver takes it.
func value(v any) any {
	switch v := v.(type) {
	case clarity.Date:
		return civil.Date{Year: v.Year, Month: v.Month, Day: v.Day}
	case clarity.DateTime:
		return civil.DateTime{
			Date: civil.Date{Year: v.Year, Month: v.Month, Day: v.Day},
			Time: civil.Time{Hour: v.Hour, Minute: v.Minute, Second: v.Second},
		}
	}
	return v
}

func open(location string) (clarity.Server, error) {
	connector, err := mssql.NewConnector(location)
	if err != nil {
		return clarity.Server{}, err
	}
	isReference := func(err error) bool {
		var e mssql.Error
		return errors.As(err, &e) && e.Number == foreignKey
	}
	return clarity.Server{DB: sql.OpenDB(connector), IsReference: isReference, Value: value, Returning: true, Undoes: true}, nil
}
